using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 changed discriminator from "Discriminator" to "$type".
            // Preserve old property name for compatibility with existing 500K documents.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 changed id format from "EntityName|<key>" to just "<key>".
            // Preserve old format for compatibility with existing documents.
            entity.HasIdProperty("id");
            entity.Property<string>("__id")
                .ToJsonProperty("id");
            // Use the legacy id format so existing "Product|123" values still resolve.
            entity.HasPartitionKey(p => p.Id);
        });
    }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "ProductsDb",
            cosmosOptions =>
            {
                // EF Core 9 removed synchronous I/O support for Cosmos.
                // All queries must use async APIs (ToListAsync, FirstOrDefaultAsync, etc.)
            });
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

