using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // BREAKING CHANGE #1: Discriminator property renamed "$type" in EF Core 9.
            // Opt back into the legacy property name so existing documents still match.
            entity.HasDiscriminator<string>("Discriminator");

            // BREAKING CHANGE #2: id values no longer include the type prefix.
            // EF8 wrote "Product|123"; EF9 writes just "123".
            // Use IdProperty with a value generator that preserves the legacy format.
            entity.Property(p => p.Id)
                .HasConversion<string>(
                    id => $"Product|{id}",
                    str => int.Parse(str.Replace("Product|", "")));
            entity.HasPartitionKey(p => p.Id);
        });

        // BREAKING CHANGE #3: HasIndex() on Cosmos now throws.
        // Removed — manage Cosmos indexing policy in the Azure portal instead.
    }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "ProductsDb");
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

